     1→using SheetAtlas.Core.Domain.Entities;
     2→using SheetAtlas.Core.Domain.ValueObjects;
     3→using SheetAtlas.Core.Application.Interfaces;
     4→using SheetAtlas.Core.Application.DTOs;
     5→using SheetAtlas.Core.Configuration;
     6→using SheetAtlas.Logging.Services;
     7→using CsvHelper;
     8→using CsvHelper.Configuration;
     9→using Microsoft.Extensions.Options;
    10→using SheetAtlas.Logging.Models;
    11→
    12→namespace SheetAtlas.Infrastructure.External.Readers
    13→{
    14→    /// <summary>
    15→    /// Reader for CSV (Comma-Separated Values) files
    16→    /// </summary>
    17→    /// <remarks>
    18→    /// Uses CsvHelper library with auto-detection for delimiter.
    19→    /// CSV files are converted to ExcelFile with a single sheet named "Data".
    20→    /// Supports configuration via CsvReaderOptions for delimiter, encoding, and culture.
    21→    /// </remarks>
    22→    public class CsvFileReader : IConfigurableFileReader
    23→    {
    24→        private readonly ILogService _logger;
    25→        private readonly ISheetAnalysisOrchestrator _analysisOrchestrator;
    26→        private readonly ISettingsService _settingsService;
    27→        private readonly SecuritySettings _securitySettings;
    28→        private CsvReaderOptions _options;
    29→
    30→        public CsvFileReader(
    31→            ILogService logger,
    32→            ISheetAnalysisOrchestrator analysisOrchestrator,
    33→            ISettingsService settingsService,
    34→            IOptions<AppSettings> settings)
    35→        {
    36→            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    37→            _analysisOrchestrator = analysisOrchestrator ?? throw new ArgumentNullException(nameof(analysisOrchestrator));
    38→            _settingsService = settingsService ?? throw new ArgumentNullException(nameof(settingsService));
    39→            _securitySettings = settings?.Value?.Security ?? new SecuritySettings();
    40→            _options = CsvReaderOptions.Default;
    41→        }
    42→
    43→        private static readonly string[] _supportedExtensions = new[] { ".csv" };
    44→
    45→        public IReadOnlyList<string> SupportedExtensions => _supportedExtensions.AsReadOnly();
    46→
    47→        public void Configure(IReaderOptions options)
    48→        {
    49→            ArgumentNullException.ThrowIfNull(options);
    50→
    51→            if (options is not CsvReaderOptions csvOptions)
    52→                throw new ArgumentException($"Expected CsvReaderOptions but got {options.GetType().Name}", nameof(options));
    53→
    54→            _options = csvOptions;
    55→            _logger.LogInfo($"Configured CSV reader with delimiter '{_options.Delimiter}', encoding '{_options.Encoding.WebName}'", "CsvFileReader");
    56→        }
    57→
    58→        public async Task<ExcelFile> ReadAsync(string filePath, CancellationToken cancellationToken = default)
    59→        {
    60→            var errors = new List<ExcelError>();
    61→            var sheets = new Dictionary<string, SASheetData>();
    62→
    63→            // Validation: Fail fast for invalid input
    64→            if (string.IsNullOrWhiteSpace(filePath))
    65→                throw new ArgumentNullException(nameof(filePath));
    66→
    67→            try
    68→            {
    69→                // Check file size limit
    70→                var fileInfo = new FileInfo(filePath);
    71→                if (fileInfo.Length > _securitySettings.MaxFileSizeBytes)
    72→                {
    73→                    var maxMb = _securitySettings.MaxFileSizeBytes / (1024 * 1024);
    74→                    var fileMb = fileInfo.Length / (1024 * 1024);
    75→                    errors.Add(ExcelError.Critical("Security",
    76→                        $"File size ({fileMb} MB) exceeds maximum allowed ({maxMb} MB)"));
    77→                    return new ExcelFile(filePath, LoadStatus.Failed, sheets, errors);
    78→                }
    79→
    80→                return await Task.Run(async () =>
    81→                {
    82→                    // Auto-detect delimiter if using default comma
    83→                    char delimiter = _options.Delimiter;
    84→                    if (_options == CsvReaderOptions.Default)
    85→                    {
    86→                        delimiter = DetectDelimiter(filePath);
    87→                        _logger.LogInfo($"Auto-detected delimiter: '{delimiter}'", "CsvFileReader");
    88→                    }
    89→
    90→                    var config = new CsvConfiguration(_options.Culture)
    91→                    {
    92→                        Delimiter = delimiter.ToString(),
    93→                        HasHeaderRecord = _options.HasHeaderRow,
    94→                        Encoding = _options.Encoding,
    95→                        BadDataFound = null, // Ignore malformed rows instead of throwing
    96→                        MissingFieldFound = null, // Ignore missing fields
    97→                        TrimOptions = TrimOptions.Trim,
    98→                        DetectDelimiter = false // We handle detection manually
    99→                    };
