            // Determine format based on decimal places in original text
            string numericPartStr = match.Groups[1].Value;
            string format = numericPartStr.Contains('.')
                ? "0.0%"  // Has decimals: "15.5%" → format "0.0%"
                : "0%";   // Integer: "15%" → format "0%"

