            {
                if (cellText.Length > 1 && char.IsDigit(cellText[1]))
                {
                    // Looks like a number, don't sanitize
                    return cellText;
                }
                // Not a number, sanitize
                return "'" + cellText;
            }

            return cellText;
        }
