public OpenXmlFileReader(
    ILogService logger,                           // ← Comune
    ICellReferenceParser cellParser,              // Specifico
    IMergedRangeExtractor<WorksheetPart> extractor, // Specifico
    ICellValueReader cellValueReader,             // Specifico
    ISheetAnalysisOrchestrator analysisOrchestrator, // ← Comune
    ISettingsService settingsService,             // ← Comune
    IOptions<AppSettings> settings)               // ← Comune
{
    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    _cellParser = cellParser ?? throw new ArgumentNullException(nameof(cellParser));
    _mergedRangeExtractor = extractor ?? throw new ArgumentNullException(nameof(extractor));
    _cellValueReader = cellValueReader ?? throw new ArgumentNullException(nameof(cellValueReader));
    _analysisOrchestrator = analysisOrchestrator ?? throw new ArgumentNullException(nameof(analysisOrchestrator));
