   226→    /// <summary>
   227→    /// Detects the system theme preference using PlatformSettings.
   228→    /// Falls back to Light if detection fails.
   229→    /// </summary>
   230→    private static Theme DetectSystemTheme()
   231→    {
   232→        try
   233→        {
   234→            // Try PlatformSettings first (more reliable)
   235→            var platformSettings = Application.Current?.PlatformSettings;
   236→            if (platformSettings != null)
   237→            {
   238→                var colorValues = platformSettings.GetColorValues();
   239→                if (colorValues.ThemeVariant == PlatformThemeVariant.Dark)
   240→                    return Theme.Dark;
   241→            }
   242→
   243→            // Fallback to ActualThemeVariant
   244→            if (Application.Current?.ActualThemeVariant == ThemeVariant.Dark)
   245→                return Theme.Dark;
   246→        }
   247→        catch
   248→        {
   249→            // Ignore detection errors
   250→        }
   251→
   252→        return Theme.Light;
   253→    }
   254→}
